def balanced(n):
    if n < 0:
        return None
    answers = []
    def visit(text, opened, closed):
        if closed == n:
            answers.append(text)
            return
        if opened < n:
            visit(text + "(", opened + 1, closed)
        if closed < opened:
            visit(text + ")", opened, closed + 1)
    visit("", 0, 0)
    return answers

print(balanced(2))
print(balanced(0))

def simple_paths(adjacency, start, target):
    n = len(adjacency)
    if start < 0 or start >= n or target < 0 or target >= n:
        return None
    used = [False] * n
    answers = []
    path = []
    def visit(vertex):
        used[vertex] = True
        path.append(vertex)
        if vertex == target:
            answers.append(path.copy())
        else:
            for neighbor in adjacency[vertex]:
                if not used[neighbor]:
                    visit(neighbor)
        path.pop()
        used[vertex] = False
    visit(start)
    return answers

graph = [[1, 2], [0, 2, 3], [3], []]
print(simple_paths(graph, 0, 3))
print(simple_paths(graph, 2, 2))

def subset_sum(values, target, prune):
    if target < 0:
        return None
    for value in values:
        if value < 0:
            return None
    n = len(values)
    suffix = [0] * (n + 1)
    for index in range(n - 1, -1, -1):
        suffix[index] = suffix[index + 1] + values[index]
    answers = []
    path = []
    calls = [0]
    def visit(index, total):
        calls[0] = calls[0] + 1
        if prune and (total > target or total + suffix[index] < target):
            return
        if index == n:
            if total == target:
                answers.append(path.copy())
            return
        visit(index + 1, total)
        path.append(index)
        visit(index + 1, total + values[index])
        path.pop()
    visit(0, 0)
    return {"solutions": answers, "calls": calls[0]}

print(subset_sum([2, 3, 5], 5, True)["solutions"])
print(subset_sum([0], 0, True)["solutions"])
print(subset_sum([-1, 2], 1, True))

def queens(n):
    if n < 0:
        return None
    answers = []
    columns = []
    def visit(row):
        if row == n:
            answers.append(columns.copy())
            return
        for column in range(n):
            safe = True
            for previous in range(row):
                gap = row - previous
                old = columns[previous]
                if old == column or old - column == gap or column - old == gap:
                    safe = False
            if safe:
                columns.append(column)
                visit(row + 1)
                columns.pop()
    visit(0)
    return answers

